-- Paket ABT "abt-x5-kodepos-amplop-21okt" (21 Okt 2026): kode pos di ujung alamat penerima pada amplop relaas.
-- Variabel baru 9290-9293 (kode pos dari kode wilayah pihak; alamat + kode pos) dan 8172 diubah; 6 blangko amplop Derry disunting satu penanda (berkas_rtf.py).
-- 4 variabel baru, 1 baris diubah.
-- PULIH (deterministik): variabel baru dihapus HANYA bila isinya masih persis paket; baris yang diubah dikembalikan dari tabel sementara x5_lama
-- (dibuat pulih-satker.sh dari cadangan/abt_variabel-sebelum.sql) HANYA bila isinya masih isi BARU paket dan baris cadangan masih isi LAMA yang diharapkan.
-- Jalankan lewat pulih-satker.sh (bukan langsung): tabel x5_lama harus ada.
START TRANSACTION;
DELETE FROM abt_variabel WHERE (no_var=9290 AND MD5(nama)='e6a090ac9cc353e4d8655d8a20c1c2be' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='470dd6add4d2054c150f4d79f9a28de8' AND IFNULL(MD5(default_data),'-')='-');
DELETE FROM abt_variabel WHERE (no_var=9291 AND MD5(nama)='dc88156127161e1e5e1c1f3d5dabbc8a' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='d3b043fa44636f52de26b0896b475c74' AND IFNULL(MD5(default_data),'-')='-');
DELETE FROM abt_variabel WHERE (no_var=9292 AND MD5(nama)='26059ed1ccf7f124f445925278090eb4' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='f0e51968dd27a186dd9b5373a4ccb208' AND IFNULL(MD5(default_data),'-')='-');
DELETE FROM abt_variabel WHERE (no_var=9293 AND MD5(nama)='77298f3b85bd63c58a274022db1611af' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='f484a6d9952ca1fae290c7fef266e0bd' AND IFNULL(MD5(default_data),'-')='-');
UPDATE abt_variabel a JOIN x5_lama l ON l.no_var=a.no_var SET a.nama=l.nama, a.data_type=l.data_type, a.data_tabel=l.data_tabel, a.data_kolom=l.data_kolom, a.urutan_data=l.urutan_data, a.referensi=l.referensi, a.sql_query=l.sql_query, a.default_data=l.default_data, a.multi_sidang=l.multi_sidang, a.locked=l.locked, a.modifier=l.modifier, a.modified=l.modified WHERE (a.no_var=8172 AND MD5(a.nama)='e0becf55b9e3c385cfc47911dd9bbce9' AND a.data_type='data_sql' AND MD5(a.sql_query)='f5a7bc688de1254b8f45445c5086d817') AND (l.no_var=8172 AND MD5(l.nama)='e0becf55b9e3c385cfc47911dd9bbce9' AND l.data_type='data_sql' AND MD5(l.sql_query)='bf7b5de148ddf1b8640de12667fe339a');
COMMIT;
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (9290,9291,9292,9293)) = 0 AND (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=8172 AND MD5(nama)='e0becf55b9e3c385cfc47911dd9bbce9' AND data_type='data_sql' AND MD5(sql_query)='bf7b5de148ddf1b8640de12667fe339a'))) = 1, 'PULIH COCOK', CONCAT('PULIH TIDAK LENGKAP - nomor baru tersisa ', (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (9290,9291,9292,9293)), ', baris diubah yang sudah kembali ', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=8172 AND MD5(nama)='e0becf55b9e3c385cfc47911dd9bbce9' AND data_type='data_sql' AND MD5(sql_query)='bf7b5de148ddf1b8640de12667fe339a'))), ' dari 1 (diubah orang sesudah dipasang? dibiarkan)')) AS hasil;
